def document_lines(value):
    if isinstance(value,str):return re.findall(r'DOCUMENT-\d+ LINE-\d+',value)
    if isinstance(value,list):return [line for v in value for line in document_lines(v)]
    if isinstance(value,dict):
        from common.currency import value_result_payload
        is_value,payload=value_result_payload(value)
        if is_value:return document_lines(payload)
        if isinstance(value.get('items'),list):return document_lines(value['items'])
        return [line for v in value.values() for line in document_lines(v)]
    return []

