"""Replay saved programs; no model calls and no changes to primary trial records."""
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path('/Users/kangkukjin/Desktop/AI/indiebizOS')
sys.path.insert(0, str(ROOT / 'backend'))
import boot_paths  # noqa: E402,F401

OUT = Path(__file__).resolve().parent
trials = [json.loads(f.read_text()) for f in sorted((OUT / 'trials').glob('*.json'))]
registry = json.loads((OUT / 'registry.json').read_text())
audits = {}
for kind in ('schema', 'semantic'):
    path = OUT / f'{kind}_audit.json'
    rows = json.loads(path.read_text()) if path.exists() else []
    known = {(r['id'], r['attempt']) for r in rows}
    for trial in trials:
        for index, attempt in enumerate(trial['attempts']):
            key = (trial['id'], index)
            if key in known:
                continue
            if not attempt['code']:
                result = {'quality_ok': False, 'verdict': 'No executable program was delivered'}
            else:
                req = {'code': attempt['code'], 'case_id': trial['case'], 'seed': trial['seed'], 'registry': registry}
                proc = subprocess.run([sys.executable, str(OUT / f'{kind}_audit_worker.py')], input=json.dumps(req), text=True, capture_output=True, cwd=ROOT, timeout=30)
                if proc.returncode:
                    raise RuntimeError(proc.stderr[-1800:])
                result = json.loads(proc.stdout)
            rows.append({'id': trial['id'], 'attempt': index, 'primary': attempt['execution']['quality_ok'], 'audit': result})
        path.write_text(json.dumps(rows, ensure_ascii=False, indent=2) + '\n')
    audits[kind] = {(r['id'], r['attempt']): r['audit'] for r in rows}
    print(kind, len(rows), 'attempts', flush=True)

summary = {'groups': {}, 'cases': {}, 'schema_differences': [], 'requirement_differences': []}
for trial in trials:
    for index, attempt in enumerate(trial['attempts']):
        key = (trial['id'], index)
        for kind, target in [('schema', 'schema_differences'), ('semantic', 'requirement_differences')]:
            outcome = audits[kind][key]
            if bool(outcome['quality_ok']) != bool(attempt['execution']['quality_ok']):
                summary[target].append({'id': trial['id'], 'attempt': index, 'primary': attempt['execution']['quality_ok'], 'audited': outcome['quality_ok'], 'verdict': outcome['verdict']})

def stats(rows):
    first = [audits['semantic'][(r['id'], 0)]['quality_ok'] for r in rows]
    final = [audits['semantic'][(r['id'], len(r['attempts']) - 1)]['quality_ok'] for r in rows]
    return {'n': len(rows), 'first_requirement_ok': sum(first), 'final_requirement_ok': sum(final),
            'ever_requirement_ok': sum(any(audits['semantic'][(r['id'], i)]['quality_ok'] for i in range(len(r['attempts']))) for r in rows),
            'first_correct_then_regressed': sum(a and not b for a, b in zip(first, final)),
            'first_correct_with_runtime_error': sum(bool(audits['semantic'][(r['id'], 0)]['quality_ok']) and (audits['semantic'][(r['id'], 0)].get('result') or {}).get('success') is False for r in rows)}

for group in ('all', 'applicable', 'direct', 'embedded', 'counter'):
    rows = [r for r in trials if group == 'all' or (group == 'applicable' and r['group'] != 'counter') or r['group'] == group]
    summary['groups'][group] = {arm: stats([r for r in rows if r['arm'] == arm]) for arm in ('hidden', 'exposed')}
for case in sorted({r['case'] for r in trials}):
    summary['cases'][case] = {arm: stats([r for r in trials if r['case'] == case and r['arm'] == arm]) for arm in ('hidden', 'exposed')}
(OUT / 'audit_summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2) + '\n')
print(json.dumps(summary, ensure_ascii=False, indent=2))
